const probe = { probe: async () => { throw new Error('fixture must never call a provider or probe credentials'); } };
const deps: any = { sources, now: () => LATER, probe, loadScreen: async () => screen };
const config = parseRunConfig(JSON.stringify({ operator: 'Tzeusy', agentTool: 'claude-code', agentToolVersion: '2.1.0', agentProvider: 'anthropic', model: 'fixture-model',
  deadline: 'PT1H', agentTokenBudget: 100_000, maxRepairCycles: 3, maxQuestions: 1, audience: 'an operator', operatorIsOwner: true }));
