  pinnedRevision: { commit: pinned, label: 'fixture', consentRecord: 'PUBLIC-OBS-FIXTURE@1', pinnedAt: '2026-11-04T23:00:00.000Z' },
  startGates: { registryEntry: 'REGISTRY-ACT-FIXTURE', screeningPolicy: 'POLICY-ACT-FIXTURE' }, governed: { kind: 'non-governed', because: ['fixture has no kernel evidence drawer'] }, providerStatement: null,
  workItem: { identity: null, reason: NO_WORK_ITEM_REASON } };
const UNDERSTANDING = ['purpose', 'beneficiary', 'proposition', 'capabilities', 'components', 'choices', 'tradeOffs', 'limits', 'terminology', 'contradictions', 'openQuestions'];
const cite = (id: string, file = 'src/fixture.txt', startLine = 1, endLine = 7) => ({ id, path: file, startLine, endLine });
type Case = { id: string; text: string; names: string[]; local: string[]; broad: string[]; broadCount: number; inners: string[]; path?: string; range?: [number, number]; uncited?: boolean; rawQuotes?: string[] };
const L = 'The project states:';
const CASES: Case[] = [
  { id: 'straight-normalised', text: `${L} "alpha beta gamma."`, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha beta gamma.'], rawQuotes: ['alpha **beta** gamma.'] },
  { id: 'curly-opener', text: `${L} \u201calpha beta gamma.\u201d`, names: [], local: ['lead-in-without-quote'], broad: [], broadCount: 1, inners: [] },
  { id: 'ordinary-altered', text: 'An "invented" description.', names: [], local: [], broad: ['quote-not-in-cited-sources'], broadCount: 1, inners: [], rawQuotes: [] },
  { id: 'ordinary-verified', text: 'An ordinary "delta."', names: [], local: [], broad: [], broadCount: 1, inners: [], rawQuotes: [] },
  { id: 'ordinary-before', text: `"delta." Then ${L} "alpha beta gamma."`, names: ['c'], local: [], broad: [], broadCount: 2, inners: ['alpha beta gamma.'], rawQuotes: ['alpha **beta** gamma.'] },
  { id: 'stray-before', text: `"preface ${L} "alpha"`, names: ['c'], local: [], broad: ['quote-not-in-cited-sources'], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] },
  { id: 'curly-outer', text: `\u201c${L} "alpha"\u201d`, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] },
  { id: 'straight-outer', text: `"outer ${L} "alpha" tail"`, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha" tail'], rawQuotes: ['alpha" tail'] },
  { id: 'next-lead-in-quoted-terms', text: `${L} "alpha "beta" gamma." Next ${L} "delta."`, names: ['c', 'c2'], local: [], broad: [], broadCount: 2, inners: ['alpha "beta" gamma.', 'delta.'], rawQuotes: ['alpha "beta" gamma.', 'delta.'] },
  { id: 'literal-nested-lead-in', text: `${L} "alpha ${L} "delta."`, names: ['c', 'c2'], local: ['quotation-unterminated'], broad: ['unterminated-quote'], broadCount: 2, inners: ['delta.'] },
  { id: 'missing-opener', text: `${L} alpha`, names: [], local: ['lead-in-without-quote'], broad: ['lead-in-without-quote'], broadCount: 0, inners: [] },
  { id: 'empty', text: `${L} ""`, names: ['c'], local: ['quotation-empty'], broad: ['empty-quote'], broadCount: 1, inners: [''] },
  { id: 'unterminated', text: `${L} "alpha`, names: ['c'], local: ['quotation-unterminated'], broad: ['unterminated-quote'], broadCount: 1, inners: [] },
  { id: 'altered', text: `${L} "alpha beta altered."`, names: ['c'], local: ['quotation-not-in-cited-file'], broad: ['quote-not-in-cited-sources'], broadCount: 1, inners: ['alpha beta altered.'] },
  { id: 'appended-unverified', text: `${L} "alpha beta gamma." plus "invented"`, names: ['c'], local: ['quotation-not-in-cited-file'], broad: ['quote-not-in-cited-sources'], broadCount: 1, inners: ['alpha beta gamma." plus "invented'] },
  { id: 'wrong-citation', text: `${L} "alpha"`, names: ['missing'], local: ['quotation-citation'], broad: [], broadCount: 1, inners: ['alpha'] },
  { id: 'uncited', text: `${L} "alpha"`, names: ['c'], uncited: true, local: ['schema', 'citation-by-kind', 'quotation-citation'], broad: ['quote-without-cited-source'], broadCount: 1, inners: ['alpha'] },
  { id: 'missing-source', text: `${L} "alpha"`, names: ['c'], path: 'src/absent.txt', local: ['path-absent'], broad: ['quote-without-cited-source'], broadCount: 1, inners: ['alpha'] },
  { id: 'outside-range', text: `${L} "alpha beta gamma."`, names: ['c'], range: [1, 1], local: ['quotation-outside-range'], broad: [], broadCount: 1, inners: ['alpha beta gamma.'] },
  { id: 'range-beyond', text: `${L} "alpha"`, names: ['c'], range: [1, 999], local: ['range-beyond-blob'], broad: [], broadCount: 1, inners: ['alpha'] },
  { id: 'joined', text: `${L} "delta. alpha beta gamma."`, names: ['c'], local: ['quotation-not-in-cited-file'], broad: ['quote-not-in-cited-sources'], broadCount: 1, inners: ['delta. alpha beta gamma.'] },
  { id: 'elided', text: `${L} "alpha ... gamma."`, names: ['c'], local: ['quotation-elided'], broad: ['elided-quote'], broadCount: 1, inners: ['alpha ... gamma.'] },
  { id: 'excluded-source', text: `${L} "Inert fixture text."`, names: ['c'], path: '.env', local: [], broad: ['quote-without-cited-source'], broadCount: 1, inners: ['Inert fixture text.'], rawQuotes: [] },
  { id: 'no-quotations', text: 'Plain prose.', names: [], local: [], broad: [], broadCount: 0, inners: [], rawQuotes: [] },
  ...['\r\n', '\r', '\n'].map((whitespace, i): Case => ({ id: `opener-whitespace-${i}`, text: `${L}${whitespace}"alpha"`, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] })),
  { id: 'inline-markup', text: `\`${L} "alpha"\``, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] },
  { id: 'fenced-markup', text: '```text\n' + `${L} "alpha"` + '\n```', names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] },
  { id: 'utf16-offset', text: `\u{1f600} Caf\u00e9 ${L} "alpha"`, names: ['c'], local: [], broad: [], broadCount: 1, inners: ['alpha'], rawQuotes: ['alpha'] },
];
const report: any = { schema: 'quotation-real-callers/1', subjectCommit: execFileSync('git', ['-C', SUBJECT, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(), fixture: { root: ROOT, pinned, objectId, raw: RAW, rawSha256: createHash('sha256').update(RAW).digest('hex') }, cases: [], errors: [], boundary: 'synthetic owned Git blobs only; injected fixture gates; actual checker and renderer; no observed repository or provider' };
const save = () => fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
save();
const makeDraft = (c: Case): any => ({ schemaVersion: 'polaris-dossier-local-draft-v2', pinnedRevision: pinned, sessionId: 'authoring-fixture', title: 'Quote fixture',
  introduction: { id: 'intro', label: 'inferred', basis: 'source', text: c.text, citations: c.uncited ? [] : [cite('c', c.path, ...(c.range ?? [1, 7])), ...(c.names.includes('c2') ? [cite('c2')] : [])], quotations: c.names },
  understanding: Object.fromEntries(UNDERSTANDING.map(key => [key, [{ id: `u-${key}`, label: 'inferred', statement: 'Fixture understanding.', scope: 'Fixture.', citations: [cite(`u-${key}-c`)] }]])),
  sections: [{ id: 'core-ideas', title: 'Core ideas', paragraphs: [{ id: 'p1', label: 'non-normative', text: 'Read on.', children: [] }], disposition: { kind: 'produced', assetIds: ['core-ideas'] } }],
  diagrams: [], deepDives: [], unresolved: [], discovery: { inspected: ['src/fixture.txt'], selected: [], excluded: [], unresolved: [], deferred: [], stoppingReason: 'Finite fixture.' }, clarifications: [], executions: [] });
const byteRange = (raw: string) => { const at = Buffer.from(RAW).indexOf(Buffer.from(raw)); assert(at >= 0); return [at, at + Buffer.byteLength(raw)]; };

for (let i = 0; i < CASES.length; i++) {
  const c = CASES[i]!;
  const runId = `run-${i.toString(16).padStart(32, '0')}`;
  const run = path.join(ROOT, 'runs', runId); fs.mkdirSync(run, { recursive: true });
  fs.writeFileSync(path.join(run, 'run.json'), encodeRunRecord(config.config, subject));
  const brief = await issueBrief(run, { sources, now: () => NOW });
  assert(brief.ok, JSON.stringify(brief));
  const doc = makeDraft(c);
  fs.mkdirSync(path.join(run, 'drafts'), { recursive: true });
  fs.writeFileSync(path.join(run, 'drafts', 'next.json'), JSON.stringify(doc));
  const checked = await checkDraft(run, {}, deps);
  assert(checked.ok, JSON.stringify(checked));
  const admitted = !c.uncited && (c.path === undefined || c.path === 'src/fixture.txt');
  const map = admitted ? new Map([['s', RAW]]) : new Map<string, string>();
  const block = { id: 'intro', text: c.text, sourceIds: admitted ? ['s'] : [] };
  const broad = inspectBlockQuotes(block, map);
  const inspected = leadInQuotations(c.text);
  const spans = leadInQuotationSpans(c.text);
  let captured: any;
  const rendered = await renderRun(run, { ...deps, renderer: (input: any) => { captured = input; return renderLocalDossier(input); } });
  const actual: any = { id: c.id, input: c, run, localOutcome: checked.report.outcome, localFindings: checked.report.findings,
    verified: checked.report.quotations, excluded: checked.report.excludedContent, broad, broadRepair: broad.findings.map(quoteFindingAsReviewFinding), inspected, spans,
    render: rendered, renderedBlock: captured?.local.blocks.get('intro') ?? null };
  if (rendered.ok) {
    const files: { path: string; bytes: number; sha256: string }[] = [];
    const walk = (dir: string) => { for (const item of fs.readdirSync(dir, { withFileTypes: true })) {
      const file = path.join(dir, item.name);
      if (item.isDirectory()) walk(file);
      else { const bytes = fs.readFileSync(file); files.push({ path: path.relative(rendered.report.site, file), bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') }); }
    } };
    walk(rendered.report.site);
    actual.renderedFiles = files.sort((a, b) => a.path.localeCompare(b.path));
  }
  report.cases.push(actual); save();
  const check = (name: string, a: unknown, b: unknown) => { try { assert.deepEqual(a, b, `${c.id}: ${name}`); } catch (error) { report.errors.push(String(error)); } };
  check('local finding vocabulary and order', checked.report.findings.map((f: any) => f.kind), c.local);
  check('broad finding vocabulary and order', broad.findings.map(f => f.kind), c.broad);
  check('broad real source quote count', broad.quotes, c.broadCount);
  check('local terminated span literals', spans.map(s => s.inner), c.inners);
  check('whole-draft broad seam', checkDraftQuotes({ introduction: block }, map), broad.findings);
  check('render accepted iff local findings absent', rendered.ok, c.local.length === 0);
  if (rendered.ok) {
    check('no readiness from missing reviews', rendered.report.fidelityReview.counts, false);
    check('literal rendered quotation bytes', actual.renderedBlock.segments.filter((s: any) => s.kind === 'quotation').map((s: any) => s.text), c.rawQuotes);
    check('independent pinned byte ranges', checked.report.quotations.map((q: any) => q.byteRange), (c.rawQuotes ?? []).map(byteRange));
    if (c.id === 'excluded-source') check('excluded block withheld', actual.renderedBlock.segments.filter((s: any) => s.kind === 'withheld'), [{ kind: 'withheld', reason: 'excluded-content' }]);
    check('claim stays Unknown without fidelity evidence', actual.renderedBlock.marking, 'unknown');
  } else check('actual local render refusal stage', rendered.refusal.stage, 'draft');
  // The independent inventory invokes the same derivation over its own statement field.
  const inventory = { schemaVersion: 'polaris-dossier-local-inventory-v1', pinnedRevision: pinned, sessionId: 'inventory-fixture', entries: [{ id: 'e1', kind: 'purpose', label: 'inferred', statement: c.text,
    citations: doc.introduction.citations, quotations: c.names }], coverage: { inspected: ['src/fixture.txt'], excluded: [], deferred: [], stoppingReason: 'Finite fixture.' } };
  const inv = await deriveFindings(inventory, { pinned, screen: screen.screen, reader: openPinnedObjectReader({ gitDir: path.join(ORIGIN, '.git'), revision: pinned }) }, inventoryRules(pinned));
  actual.inventory = { findings: inv.findings, quotations: inv.quotations, excluded: inv.excludedContent };
  check('inventory finding kinds', inv.findings.map(f => f.kind), c.local);
  // Repeated/reordered source maps may exercise the normalisation cache, but may not change an answer.
  inspectBlockQuotes({ id: 'other', text: '"changed"', sourceIds: ['s'] }, new Map([['s', 'other bytes']]));
  check('reentrant broad call', inspectBlockQuotes(block, map), broad);
  check('reentrant local call', leadInQuotations(c.text), inspected);
  save();
}
report.summary = { cases: CASES.length, localPassed: report.cases.filter((c: any) => c.localOutcome === 'passed').length, broadPassed: report.cases.filter((c: any) => c.broad.findings.length === 0).length,
  actualRenderAccepted: report.cases.filter((c: any) => c.render.ok).length, errors: report.errors.length };
save();
console.log(JSON.stringify(report.summary));
assert.equal(report.errors.length, 0, report.errors.join('\n'));

