import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { validateVerdict } from '../subject/packages/polaris-dossier/src/review-verdict.ts';
import { validateDesignVerdict } from '../subject/packages/polaris-dossier/src/design-review.ts';
import { fidelity, scanDossierPage } from '../subject/packages/polaris-generation-core/src/dossier-evaluation.ts';
import { generationSourcesForBody, gitBlobObjectId } from '../subject/packages/polaris-generation-core/src/generation-source.ts';

const OWN = path.resolve(import.meta.dirname, '..');
const OUT = process.argv[2] ?? path.join(OWN, 'secondary-callers-attempt2.json');
const base = JSON.parse(fs.readFileSync(path.join(OWN, 'real-callers-attempt2.json'), 'utf8'));
const first = base.cases[0];
const doc = JSON.parse(fs.readFileSync(path.join(first.run, 'drafts/rev-0.json'), 'utf8'));
const pinned = base.fixture.pinned, digest = 'a'.repeat(64);
const built: any = { ok: true, sha256: digest, draft: { doc }, inventory: { sessionId: 'inventory-fixture', doc: { entries: [{ id: 'e1' }] } }, spans: [{ id: 'span-0', outcome: 'admitted', text: base.fixture.raw }] };
const verdict = (reason: string, quotations: string[]) => ({ schemaVersion: 'polaris-dossier-local-fidelity-verdict-v1', pinnedRevision: pinned, packetSha256: digest, sessionId: 'independent-reviewer-fixture',
  inventoryCoverage: [{ entryId: 'e1', disposition: 'represented', blockIds: ['intro'], reason: 'Introduction.', quotations: [] }], inventoryAccuracy: [{ entryId: 'e1', accuracy: 'accurate', spanIds: ['span-0'], reason: 'Fixture.', quotations: [] }], blockSupport: [{ blockId: 'intro', verdict: 'supported', spanIds: ['span-0'], reason, quotations }, { blockId: 'p1', verdict: 'supported', spanIds: [], reason: 'Non-normative.', quotations: [] }], findings: [], readiness: 'ready' });
const cases = [
  { id: 'explicit-valid', text: 'The project states: "alpha"', named: ['span-0'], expected: [] },
  { id: 'explicit-altered', text: 'The project states: "invented"', named: ['span-0'], expected: ['quotation-unverified'] },
  { id: 'curly-opener', text: 'The project states: \u201calpha\u201d', named: [], expected: ['quotation-count', 'quotation-unverified'] },
  { id: 'ordinary-prose', text: 'An "invented" description.', named: [], expected: [] },
  { id: 'missing-opener', text: 'The project states: alpha', named: [], expected: ['quotation-count', 'quotation-unverified'] },
  { id: 'empty-quote', text: 'The project states: ""', named: ['span-0'], expected: ['quotation-unverified'] },
  { id: 'missing-span', text: 'The project states: "alpha"', named: ['span-999'], expected: ['quotation-span'] },
];
const result: any = { schema: 'quotation-secondary-callers/1', limitation: 'validator seams with a synthetic packet shape and real pinned fixture text; not an independent reviewer verdict or a full fidelity-session lifecycle', fidelity: [], design: [], evaluation: [] };
for (const c of cases) {
